EXPLANATION = {"title": "Chain Integrity", "principle": "Sequential C-alpha atoms stay within 4.5 Angstrom of each other.", "rationale": "The pinned code measures the maximum CA(i)-CA(i+1) distance for sequential same-chain residues (ideal ~3.8 A); values above 4.5 A indicate a chain break. WP-8: previous text described a 4.2 A cutoff the pinned code does not use."}
